import hashlib


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if not isinstance(certificate, (bytes, bytearray)):
        raise TypeError("certificate must be bytes or bytearray")
    if not isinstance(known_hash, str):
        raise TypeError("known_hash must be a string")

    # Calculate SHA-256 hash of the certificate
    cert_hash = hashlib.sha256(certificate).hexdigest()

    # Use constant-time comparison to prevent timing attacks
    return hashlib.compare_digest(cert_hash, known_hash)

